import RNA, re
def decompose(ss):
    n=len(ss); stack=[]; pairs={}
    for i,c in enumerate(ss):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop(); pairs[j]=i; pairs[i]=j
    # hairpin loops = ( immediately followed by dots then )
    hairpins=[(m.start(), m.end()-1, m.end()-m.start()-2) for m in re.finditer(r'\((\.+)\)', ss)]
    # helices: maximal runs of stacked pairs
    helices=0
    opens=sorted([i for i in pairs if pairs[i]>i])
    prev=None
    for i in opens:
        if prev is not None and i==prev+1 and pairs[i]==pairs[prev]-1:
            pass
        else:
            helices+=1
        prev=i
    unpaired=ss.count('.')
    return dict(len=n, bp=len(pairs)//2, unpaired=unpaired,
                paired_frac=(len(pairs))/n, helices=helices, hairpin_loops=hairpins)

