for n,r in results.items():
    s=r['seq']; ss=r['ss']; N=len(s)
    fc=RNA.fold_compound(s); _,mfe=fc.mfe(); fc.exp_params_rescale(mfe); fc.pf()
    bpp=fc.bpp()
    p=[[0.0]*(N+1) for _ in range(N+1)]
    for i in range(1,N+1):
        for j in range(i+1,N+1):
            p[i][j]=p[j][i]=bpp[i][j]
    stack=[];pairs={}
    for k,c in enumerate(ss,1):
        if c=='(':stack.append(k)
        elif c==')':
            a=stack.pop();pairs[a]=k;pairs[k]=a
    d=0.0
    for i in range(1,N+1):
        if i in pairs: d += 1-p[i][pairs[i]]
        else:          d += sum(p[i][j] for j in range(1,N+1))
    print(f"{n}: absolute ensemble defect = {d:.2f} nt of {N}  ({100*d/N:.1f}%) | API value {fc.ensemble_defect(ss):.3f}")

